Do not provide any other text or markdown fences.

Here is the original GNU C++17 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;
using lint = long long;
constexpr int MAX = 510;
int N, M, P;
lint C[MAX][MAX], F[MAX], G[MAX];
lint DP[MAX][MAX], Ways[MAX][MAX];
lint DPtmp[MAX][MAX], Waystmp[MAX][MAX];
lint DPold[MAX][MAX], Waysold[MAX][MAX];

static inline void Add(lint &x, lint y) { x = (x + y) % P; }
static inline lint C2(lint x) { return (x * (x - 1) / 2) % P; }

int main() {
    cin.tie(nullptr)->sync_with_stdio(false);
    cin >> N >> M >> P;
    for (int i = 0; i < MAX; ++i) C[i][0] = 1;
    for (int i = 1; i < MAX; ++i) {
        for (int j = 1; j <= i; ++j) {
            C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % P;
        }
    }

    F[0] = 0; G[0] = 1;
    for (int i = 1; i <= M; ++i) {
        for (int j = 1; j <= i; ++j) {
            lint t1 = C[i - 1][j - 1] * F[j - 1] % P * G[i - j] % P * (i + 1) % P;
            lint t2 = C[i - 1][j - 1] * G[j - 1] % P * F[i - j] % P * (i + 1) % P;
            lint t3 = C[i - 1][j - 1] * G[j - 1] % P * G[i - j] % P
                      * ((C2(j) + C2(i - j + 1)) % P) % P;
            Add(F[i], (t1 + t2 + t3) % P);
            Add(G[i], C[i - 1][j - 1] * G[j - 1] % P * G[i - j] % P * (i + 1) % P);
        }
    }

    DP[0][0] = 0; Ways[0][0] = 1;
    for (int i = 0; i < N; ++i) {
        memset(DPtmp, 0, sizeof(DPtmp));
        memset(Waystmp, 0, sizeof(Waystmp));
        for (int j = 0; j <= min(i, M); ++j) {
            for (int k = 0; k <= min(j, M); ++k) {
                if (k == 0) {
                    DPold[i][j] = DP[j][0];
                    Waysold[i][j] = Ways[j][0];
                }
                Add(DPtmp[j][0], DP[j][k]);
                Add(Waystmp[j][0], Ways[j][k]);
                int rem = M - (j - k);
                Add(Waystmp[j + 1][k + 1], Waysold[i - k][j - k] * C[rem][k + 1] % P * G[k + 1] % P);
                Add(DPtmp[j + 1][k + 1], DPold[i - k][j - k] * C[rem][k + 1] % P * G[k + 1] % P
                                        + Waysold[i - k][j - k] * C[rem][k + 1] % P * F[k + 1] % P);
            }
        }
        for (int j = 0; j < MAX; ++j) {
            for (int k = 0; k < MAX; ++k) {
                DP[j][k] = DPtmp[j][k];
                Ways[j][k] = Waystmp[j][k];
            }
        }
    }

    lint ans = 0;
    for (int i = 0; i <= M; ++i) Add(ans, DP[M][i]);
    cout << ans << '\n';
    return 0;
}
